{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/real-user/claude-code-data-collective/schema/contribution.schema.json",
  "title": "CCDC per-contribution metadata file (contribution.json)",
  "description": "Thin, contributor-authored metadata committed alongside each contribution. Declares only identity, license affirmation, and attestation; all provenance is CI-derived. See SCHEMA.md.",
  "type": "object",
  "additionalProperties": false,
  "required": ["schema_version", "contributor_id", "license", "attestation"],
  "properties": {
    "schema_version": {
      "const": "1",
      "description": "Version of this contribution.json schema."
    },
    "contributor_id": {
      "type": "string",
      "pattern": "^[a-z0-9][a-z0-9-]{0,38}$",
      "description": "Stable contributor handle. Must equal the <contributor_id> path segment."
    },
    "license": {
      "const": "CCDC-1.0",
      "description": "Affirmation that this contribution is licensed under the CCDC Data License v1.0."
    },
    "attestation": {
      "type": "object",
      "additionalProperties": false,
      "required": ["right_to_contribute", "original_retained"],
      "properties": {
        "right_to_contribute": {
          "const": true,
          "description": "The contributor affirms they have the right to contribute this data."
        },
        "original_retained": {
          "const": true,
          "description": "The contributor affirms they retain the original input for possible re-sanitization."
        }
      }
    }
  }
}

